B.aY4=new A.hj("2000-01-14","\uc2dc\uacc4 \ub2e4\uc12f \uac1c\uac00 \uac19\uc544\uc84c\ub2e4","\uc9c0\uc548\uc774 \ud2b8\ub808\uc774\ub529 \ud50c\ub85c\uc5b4 \uc2dc\uacc4\ub97c \uc804\ubd80 \ub9de\ucdc4\ub2e4. \uc18c\uc720\uc790 \ud655\uc778\uacfc \uc804\uc6d0 \ucc28\ub2e8, \ub450 \uba85 \uc785\ud68c\uae4c\uc9c0 \uc9c0\ucf1c\uc11c \uc774\ubc88\uc5d0\ub294 \uc544\ubb34\ub3c4 \ub180\ub77c\uc9c0 \uc54a\uc558\ub2e4. \uc21c\uc11c\uac00 \uaddc\uce59\uc774 \ub41c \uccab \uc0ac\ub840\ub85c \uae30\ub85d\ub410\ub2e4.","\uc815\ube44",B.iI,4287605176,"assets/images/cinematic_soft_painted/decimal/bg_decimal_electronics_workshop_2000_v1.png")
B.aY5=new A.hj("2000-01-21","\uc218\uc544\uc758 \uc18c\ubb38 \uacf5\ucc45","\uc218\uc544\uac00 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub290 \ud68c\uc0ac \uc774\ub984\uc744 \uc5b4\ub514\uc11c \ucc98\uc74c \uaebc\ub0b4\ub294\uc9c0 \uc801\uae30 \uc2dc\uc791\ud588\ub2e4. \ucc44\uc544\uac00 \uadf8 \uacf5\ucc45\uc5d0 \uc5b8\uc81c \ub4e4\uc5c8\ub294\uc9c0 \uce78\uc744 \ud558\ub098 \ub354 \uadf8\uc5c8\ub2e4. \uba3c\uc800 \ub4e3\ub294 \uac83\uacfc \uba3c\uc800 \uc544\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4\uace0.","\uc18c\ubb38 \uacf5\ucc45",B.qk,4293233576,u.u)
B.aYc=new A.hj("2000-01-31","\uccab \ub2ec \uacb0\uc0b0","\ud55c\uc11c\uc724\uc774 \uccab \ub2ec \ud658\uc218\uae08\uacfc \uc790\ub9bd\uc801\ub9bd\uae08\uc744 \uac01\uac01 \uc77d\uc5b4 \uc92c\ub2e4. \ubc88 \uc0ac\ub78c\ub3c4 \uc783\uc740 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\uc9c0\ub9cc \ubc25\uacfc \uc7a0\uc790\ub9ac\ub294 \uadf8\ub300\ub85c\uc600\ub2e4. \uacc4\uc57d\uc11c \uccab \uc7a5\uc774 \uc0ac\uc2e4\uc774\ub77c\ub294 \uac8c \ud655\uc778\ub41c \ub0a0.","\uc6d4 \uacb0\uc0b0",B.eg,4294948941,u.u)
