B.ckp=new A.oZ("\uc815\ub2f5 \ub300\uc2e0 \uae30\ub85d\ubd80\ud130 \ubd10. \ud68c\uc0ac\uac00 \uc804\uc5d0 \ud55c \ub9d0\uc744 \uc2e4\uc81c\ub85c \uba87 \ubc88 \uc9c0\ucf30\ub294\uc9c0 \ud655\uc778\ud574 \ubd10.","\ub2e4\uc74c \uacf5\uc2dc\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc57d\uc18d\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ub300\uc870\ud558\uba74 \ub3fc.","\uacfc\uac70\uc758 \uc57d\uc18d \uc774\ud589\ub9cc\uc73c\ub85c \uc55e\uc73c\ub85c\uc758 \uc131\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.ckk=new A.oZ("\ud654\uba74 \uc124\uba85\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uc791\ub3d9\ud55c \uac78 \ubd10. \uccb4\uacb0\uac00\ub098 \uc81c\ud488 \uacb0\uacfc\ucc98\ub7fc \uc190\uc5d0 \uc7a1\ud788\ub294 \uac83\ubd80\ud130.","\ud45c\uc2dc\ub41c \uac12\uacfc \uc2e4\uc81c \uccb4\uacb0\xb7\uc791\ub3d9 \uacb0\uacfc\uac00 \ub2e4\uc2dc \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud574.","\uccb4\uacb0\uacfc \uc81c\ud488 \uc791\ub3d9\ub9cc\uc73c\ub85c \uc0ac\uc5c5 \uac00\uce58 \uc804\uccb4\ub97c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.cko=new A.oZ("\uac00\uaca9\uc120\uc758 \uacb0\uc774 \uac11\uc790\uae30 \ub2ec\ub77c\uc9c4 \uc790\ub9ac\ubd80\ud130 \ubd10. \uc774\uc0c1\ud558\ub2e4\ub294 \ub290\ub08c\uc740 \ub2f5\uc774 \uc544\ub2c8\ub77c \ud655\uc778 \uc2e0\ud638\uc57c.","\ub2e4\uc74c \uc6c0\uc9c1\uc784\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub9ac\ub4ec\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ubcf4\uace0 \ud310\ub2e8\ud574.","\uac00\uaca9\uc758 \uc774\uc0c1 \uc9d5\ud6c4\ub294 \uc6d0\uc778\uc774 \uc544\ub2c8\ub77c \ucd94\uac00 \ud655\uc778\uc774 \ud544\uc694\ud55c \uc2e0\ud638\ub2e4.")
B.ckq=new A.oZ("\uc0b4 \uc774\uc720\ubcf4\ub2e4 \ub098\uc62c \uc870\uac74\ubd80\ud130 \uc801\uc5b4. \uc2e4\ud589 \uc21c\uc11c\uac00 \uc5c6\uc73c\uba74 \uc88b\uc740 \uacc4\ud68d\ub3c4 \uae09\ud560 \ub54c \uc5c9\ucf1c.","\uc815\ud55c \ub9c8\uac10\uacfc \ucca0\uc218 \uc870\uac74\uc744 \uc2e4\uc81c\ub85c \uc9c0\ud0ac \uc218 \uc788\ub294\uc9c0 \uba3c\uc800 \uc810\uac80\ud574.","\uc2e4\ud589 \uacc4\ud68d\uc774 \uc88b\uc544\ub3c4 \uc218\uc694\uc640 \uac00\uaca9\uc774 \ub9de\ub294\uc9c0\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud55c\ub2e4.")
B.ckn=new A.oZ("\uc88b\uc740 \ub9d0\ubcf4\ub2e4 \ub204\uac00 \ub9d0\ud558\uc9c0 \ubabb\ud588\ub294\uc9c0 \ubd10. \uc774\ud574\uad00\uacc4\uac00 \ub9c9\ud78c \uc790\ub9ac\uc5d0 \ube60\uc9c4 \uc815\ubcf4\uac00 \uc788\uc744 \uc218 \uc788\uc5b4.","\ubc18\ub300 \uc758\uacac\uc744 \ub0bc \uc218 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uac19\uc740 \uc774\uc57c\uae30\uac00 \ub098\uc624\ub294\uc9c0 \ubb3c\uc5b4\ubd10.","\uc0ac\ub78c\ub4e4\uc758 \ubd84\uc704\uae30\ub97c \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub0b4\ubd80 \uc0ac\uc2e4\ucc98\ub7fc \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.ckm=new A.oZ("\uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc774\ub984\uc744 \ub2e4\uc2dc \uaebc\ub0b4\ub294\uc9c0 \ubd10. \ud55c \ubc88\uc758 \uc18c\ubb38\ubcf4\ub2e4 \ubc18\ubcf5\ub418\ub294 \uc218\uc694\uac00 \uc911\uc694\ud574.","\uadf8 \uad00\uc2ec\uc774 \uc2e4\uc81c \uc7ac\uad6c\ub9e4\ub098 \ub9e4\ucd9c \uc22b\uc790\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud574 \ubd10.","\uc720\ud589\uc758 \uc804\uc870\ub294 \uc77c\uc2dc\uc801\uc778 \uc18c\ubb38\uc77c \uc218 \uc788\uc73c\uba70 \ub9e4\ucd9c\uc744 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.ckl=new A.oZ("\uc9c0\uae08 \ubbff\ub294 \uc774\uc720\uac00 \ud2c0\ub9ac\ub294 \uacbd\uc6b0\ub97c \ud558\ub098 \ub9cc\ub4e4\uc5b4 \ubd10. \ubc18\ub840\uac00 \ubc84\ud2f0\uba74 \uac00\uc124\ub3c4 \ub2e4\uc2dc \ubd10\uc57c\uc9c0.","\uc5b4\ub5a4 \uc0ac\uc2e4\uc774 \ub098\uc624\uba74 \ub124 \uc0dd\uac01\uc744 \ubc14\uafc0\uc9c0 \uba3c\uc800 \uc815\ud574 \ub46c.","\ubc18\ub840 \ud558\ub098\ub9cc\uc73c\ub85c \uc6d0\ub798 \uac00\uc124 \uc804\uccb4\uac00 \ud2c0\ub838\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.ckj=new A.oZ("\ud558\ub8e8 \uac00\uaca9\ubcf4\ub2e4 \uad6c\uc870\ub97c \ubd10. \ub124 \uc804\uc81c\uac00 \ubb34\uc5c7\uc774\uace0 \uc5b8\uc81c \uae68\uc9c0\ub294\uc9c0\ubd80\ud130 \uc801\uc5b4.","\ud575\uc2ec \uc804\uc81c\uac00 \ubc14\ub00c\uc5c8\uc744 \ub54c \uc190\uc2e4 \ubc94\uc704\uac00 \uc5b4\ub514\uae4c\uc9c0\uc778\uc9c0 \ub2e4\uc2dc \uacc4\uc0b0\ud574.","\uc7a5\uae30 \uad6c\uc870\ub3c4 \uc804\uc81c\uac00 \ubc14\ub00c\uba74 \uae68\uc9c0\uba70 \ubbf8\ub798 \uacb0\uacfc\ub97c \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
